'use client'

import { Hash, Menu, Users } from 'lucide-react'
import { Channel, Message } from '@/types'
import MessageList from './MessageList'
import MessageForm from './MessageForm'

interface Props {
  channel: Channel
  messages: Message[]
  onSendMessage: (content: string) => Promise<void>
  onMenuClick: () => void
  userName: string
  memberCount?: number
}

export default function ChatArea({
  channel,
  messages,
  onSendMessage,
  onMenuClick,
  userName,
  memberCount,
}: Props) {
  return (
    <div className="flex flex-col h-full bg-white">
      {/* チャンネルヘッダー */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 bg-white shadow-sm flex-shrink-0">
        <div className="flex items-center gap-3">
          {/* モバイル用メニューボタン */}
          <button
            onClick={onMenuClick}
            className="md:hidden p-1.5 rounded-lg hover:bg-gray-100 transition-colors"
          >
            <Menu size={18} className="text-gray-600" />
          </button>

          <div className="flex items-center gap-2">
            <Hash size={18} className="text-gray-500" />
            <h1 className="font-bold text-gray-900 text-[15px]">{channel.name}</h1>
          </div>

          {channel.description && (
            <>
              <div className="w-px h-5 bg-gray-300 hidden sm:block" />
              <span className="text-sm text-gray-500 hidden sm:block truncate max-w-xs">
                {channel.description}
              </span>
            </>
          )}
        </div>

        {/* 右側: メンバー数など */}
        <div className="flex items-center gap-2 text-gray-500">
          {memberCount !== undefined && (
            <div className="flex items-center gap-1.5 text-sm">
              <Users size={15} />
              <span>{memberCount}</span>
            </div>
          )}
        </div>
      </div>

      {/* メッセージ一覧 */}
      <MessageList messages={messages} currentUserName={userName} />

      {/* 入力フォーム */}
      <div className="flex-shrink-0 border-t border-gray-100">
        <MessageForm
          onSubmit={onSendMessage}
          channelName={channel.name}
          disabled={!userName}
        />
      </div>
    </div>
  )
}
