'use client'

import { Hash, ChevronDown, User, Settings } from 'lucide-react'
import { Channel } from '@/types'

interface Props {
  channels: Channel[]
  selectedChannel: Channel | null
  onSelectChannel: (channel: Channel) => void
  userName: string
  onUserNameClick: () => void
}

export default function Sidebar({
  channels,
  selectedChannel,
  onSelectChannel,
  userName,
  onUserNameClick,
}: Props) {
  return (
    <div className="flex flex-col h-full bg-[#3B2A4A] text-[#CFC3DA] w-64 flex-shrink-0">
      {/* ワークスペース名 */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-white/10 cursor-pointer hover:bg-white/5 transition-colors">
        <div className="flex items-center gap-2 min-w-0">
          <div className="w-7 h-7 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
            <span className="text-white font-bold text-sm">A</span>
          </div>
          <span className="font-bold text-white text-[15px] truncate leading-tight">
            アクセルビジネスカレッジ
          </span>
        </div>
        <ChevronDown size={16} className="text-white/50 flex-shrink-0" />
      </div>

      {/* スクロール可能なメインエリア */}
      <div className="flex-1 overflow-y-auto custom-scrollbar py-2">
        {/* チャンネルセクション */}
        <div className="mt-2">
          <div className="flex items-center justify-between px-4 py-1">
            <span className="text-xs font-semibold text-[#9A8FAD] uppercase tracking-wider">
              チャンネル
            </span>
          </div>

          <ul className="mt-1 space-y-0.5">
            {channels.map((channel) => {
              const isActive = selectedChannel?.id === channel.id
              return (
                <li key={channel.id}>
                  <button
                    onClick={() => onSelectChannel(channel)}
                    className={`w-full flex items-center gap-2 px-4 py-1.5 text-sm rounded mx-1 transition-colors duration-100 text-left ${
                      isActive
                        ? 'bg-[#5A4570] text-white font-semibold'
                        : 'text-[#CFC3DA] hover:bg-white/10 hover:text-white'
                    }`}
                    style={{ width: 'calc(100% - 8px)' }}
                  >
                    <Hash
                      size={15}
                      className={isActive ? 'text-white' : 'text-[#9A8FAD]'}
                    />
                    <span className="truncate">{channel.name}</span>
                  </button>
                </li>
              )
            })}
          </ul>
        </div>
      </div>

      {/* ユーザープロフィール */}
      <div className="border-t border-white/10 p-3">
        <button
          onClick={onUserNameClick}
          className="w-full flex items-center gap-2.5 px-2 py-2 rounded-lg hover:bg-white/10 transition-colors group"
        >
          <div className="w-8 h-8 bg-purple-400/40 rounded-full flex items-center justify-center flex-shrink-0">
            <User size={14} className="text-white" />
          </div>
          <div className="flex-1 min-w-0 text-left">
            <div className="text-white text-sm font-medium truncate">{userName || 'ゲスト'}</div>
            <div className="text-[#9A8FAD] text-xs">オンライン</div>
          </div>
          <Settings size={14} className="text-[#9A8FAD] opacity-0 group-hover:opacity-100 transition-opacity" />
        </button>
      </div>
    </div>
  )
}
