'use client'

import { useState, useEffect, useCallback } from 'react'
import { supabase } from '@/lib/supabase'
import { Channel, Message } from '@/types'
import Sidebar from '@/components/Sidebar'
import ChatArea from '@/components/ChatArea'
import UserNameDialog from '@/components/UserNameDialog'
import { Menu } from 'lucide-react'

export default function Home() {
  const [channels, setChannels] = useState<Channel[]>([])
  const [selectedChannel, setSelectedChannel] = useState<Channel | null>(null)
  const [messages, setMessages] = useState<Message[]>([])
  const [userName, setUserName] = useState<string>('')
  const [showUserNameDialog, setShowUserNameDialog] = useState(false)
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // ユーザー名をlocalStorageから読み込む
  useEffect(() => {
    const savedName = localStorage.getItem('abc_userName')
    if (savedName) {
      setUserName(savedName)
    } else {
      setShowUserNameDialog(true)
    }
  }, [])

  // チャンネル一覧を取得
  useEffect(() => {
    const fetchChannels = async () => {
      setLoading(true)
      const { data, error } = await supabase
        .from('channels')
        .select('*')
        .order('name')

      if (error) {
        setError('チャンネルの読み込みに失敗しました')
        setLoading(false)
        return
      }

      if (data && data.length > 0) {
        setChannels(data)
        setSelectedChannel(data[0])
      }
      setLoading(false)
    }

    fetchChannels()
  }, [])

  // 選択チャンネルのメッセージを取得 + リアルタイム購読
  useEffect(() => {
    if (!selectedChannel) return

    let isMounted = true

    const fetchMessages = async () => {
      const { data, error } = await supabase
        .from('messages')
        .select('*')
        .eq('channel_id', selectedChannel.id)
        .order('created_at', { ascending: true })
        .limit(200)

      if (!error && data && isMounted) {
        setMessages(data)
      }
    }

    fetchMessages()

    // Supabase Realtimeで新着メッセージを購読
    const channel = supabase
      .channel(`room:${selectedChannel.id}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'messages',
          filter: `channel_id=eq.${selectedChannel.id}`,
        },
        (payload) => {
          if (isMounted) {
            setMessages((prev) => {
              // 重複を防ぐ
              const exists = prev.some((m) => m.id === (payload.new as Message).id)
              if (exists) return prev
              return [...prev, payload.new as Message]
            })
          }
        }
      )
      .subscribe()

    return () => {
      isMounted = false
      supabase.removeChannel(channel)
    }
  }, [selectedChannel])

  const handleSendMessage = useCallback(
    async (content: string) => {
      if (!selectedChannel || !userName) return

      const { error } = await supabase.from('messages').insert({
        channel_id: selectedChannel.id,
        user_name: userName,
        content: content,
      })

      if (error) {
        console.error('メッセージ送信エラー:', error)
        throw error
      }
    },
    [selectedChannel, userName]
  )

  const handleSetUserName = (name: string) => {
    setUserName(name)
    localStorage.setItem('abc_userName', name)
    setShowUserNameDialog(false)
  }

  const handleSelectChannel = (channel: Channel) => {
    setSelectedChannel(channel)
    setSidebarOpen(false)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-[#3B2A4A]">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-white/30 border-t-white rounded-full animate-spin mx-auto mb-4" />
          <div className="text-white/80 text-sm">読み込み中...</div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex h-screen overflow-hidden bg-[#2D1F3A]">
      {/* ユーザー名ダイアログ */}
      {showUserNameDialog && <UserNameDialog onSubmit={handleSetUserName} />}

      {/* モバイル用オーバーレイ */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-20 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* サイドバー (デスクトップ: 常時表示, モバイル: オーバーレイ) */}
      <div
        className={`
          fixed md:relative inset-y-0 left-0 z-30 md:z-auto
          transition-transform duration-300 ease-in-out
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        `}
      >
        <Sidebar
          channels={channels}
          selectedChannel={selectedChannel}
          onSelectChannel={handleSelectChannel}
          userName={userName}
          onUserNameClick={() => setShowUserNameDialog(true)}
        />
      </div>

      {/* メインコンテンツ */}
      <div className="flex-1 flex flex-col min-w-0 bg-white rounded-tl-xl overflow-hidden md:rounded-none">
        {error ? (
          <div className="flex-1 flex items-center justify-center">
            <div className="text-center p-8">
              <div className="text-red-500 text-5xl mb-4">!</div>
              <p className="text-gray-700 font-medium">{error}</p>
              <button
                onClick={() => window.location.reload()}
                className="mt-4 px-4 py-2 bg-purple-700 text-white rounded-lg hover:bg-purple-800 transition-colors text-sm"
              >
                再読み込み
              </button>
            </div>
          </div>
        ) : selectedChannel ? (
          <ChatArea
            channel={selectedChannel}
            messages={messages}
            onSendMessage={handleSendMessage}
            onMenuClick={() => setSidebarOpen(!sidebarOpen)}
            userName={userName}
          />
        ) : (
          <div className="flex-1 flex items-center justify-center">
            {/* モバイル用メニューボタン */}
            <button
              onClick={() => setSidebarOpen(true)}
              className="absolute top-4 left-4 md:hidden p-2 rounded-lg bg-gray-100"
            >
              <Menu size={20} className="text-gray-600" />
            </button>
            <div className="text-center text-gray-400">
              <p className="text-lg">チャンネルがありません</p>
              <p className="text-sm mt-1">Supabaseにチャンネルを追加してください</p>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
