'use client'

import { useEffect, useRef } from 'react'
import { format, isToday, isYesterday, isSameDay } from 'date-fns'
import { ja } from 'date-fns/locale'
import { Message } from '@/types'

interface Props {
  messages: Message[]
  currentUserName: string
}

function getAvatarColor(name: string): string {
  const colors = [
    'bg-red-500', 'bg-orange-500', 'bg-amber-500', 'bg-yellow-500',
    'bg-lime-500', 'bg-green-500', 'bg-emerald-500', 'bg-teal-500',
    'bg-cyan-500', 'bg-sky-500', 'bg-blue-500', 'bg-indigo-500',
    'bg-violet-500', 'bg-purple-500', 'bg-fuchsia-500', 'bg-pink-500',
  ]
  let hash = 0
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash)
  }
  return colors[Math.abs(hash) % colors.length]
}

function formatTime(dateStr: string): string {
  const date = new Date(dateStr)
  return format(date, 'HH:mm')
}

function formatDateSeparator(dateStr: string): string {
  const date = new Date(dateStr)
  if (isToday(date)) return '今日'
  if (isYesterday(date)) return '昨日'
  return format(date, 'yyyy年M月d日 (EEEE)', { locale: ja })
}

export default function MessageList({ messages, currentUserName }: Props) {
  const bottomRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  if (messages.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="text-center text-gray-400">
          <div className="text-5xl mb-4">💬</div>
          <p className="text-lg font-medium text-gray-500">まだメッセージがありません</p>
          <p className="text-sm mt-1">最初のメッセージを送ってみましょう</p>
        </div>
      </div>
    )
  }

  // 日付ごとにメッセージをグループ化
  const groupedMessages: { date: string; messages: Message[] }[] = []
  messages.forEach((msg) => {
    const msgDate = new Date(msg.created_at)
    const lastGroup = groupedMessages[groupedMessages.length - 1]
    if (lastGroup && isSameDay(new Date(lastGroup.date), msgDate)) {
      lastGroup.messages.push(msg)
    } else {
      groupedMessages.push({ date: msg.created_at, messages: [msg] })
    }
  })

  return (
    <div className="flex-1 overflow-y-auto message-scrollbar">
      <div className="py-4">
        {groupedMessages.map((group, groupIdx) => (
          <div key={groupIdx}>
            {/* 日付セパレーター */}
            <div className="flex items-center gap-3 px-6 my-4">
              <div className="flex-1 h-px bg-gray-200" />
              <span className="text-xs font-medium text-gray-500 px-2 py-0.5 bg-white border border-gray-200 rounded-full whitespace-nowrap">
                {formatDateSeparator(group.date)}
              </span>
              <div className="flex-1 h-px bg-gray-200" />
            </div>

            {/* メッセージ群 */}
            {group.messages.map((msg, msgIdx) => {
              const isOwn = msg.user_name === currentUserName
              const prevMsg = group.messages[msgIdx - 1]
              const isContinuation =
                prevMsg &&
                prevMsg.user_name === msg.user_name &&
                new Date(msg.created_at).getTime() -
                  new Date(prevMsg.created_at).getTime() < 5 * 60 * 1000

              return (
                <div
                  key={msg.id}
                  className={`message-item flex gap-3 px-6 py-1 hover:bg-gray-50 group ${
                    isContinuation ? 'mt-0' : 'mt-3'
                  }`}
                >
                  {/* アバター */}
                  <div className="flex-shrink-0 w-9">
                    {!isContinuation ? (
                      <div
                        className={`w-9 h-9 rounded-lg flex items-center justify-center text-white font-bold text-sm ${getAvatarColor(
                          msg.user_name
                        )}`}
                      >
                        {msg.user_name.charAt(0).toUpperCase()}
                      </div>
                    ) : (
                      <div className="w-9 h-5 flex items-center justify-center">
                        <span className="text-[10px] text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity">
                          {formatTime(msg.created_at)}
                        </span>
                      </div>
                    )}
                  </div>

                  {/* メッセージ内容 */}
                  <div className="flex-1 min-w-0">
                    {!isContinuation && (
                      <div className="flex items-baseline gap-2 mb-0.5">
                        <span
                          className={`text-sm font-bold ${
                            isOwn ? 'text-purple-700' : 'text-gray-900'
                          }`}
                        >
                          {msg.user_name}
                        </span>
                        <span className="text-xs text-gray-400">
                          {formatTime(msg.created_at)}
                        </span>
                      </div>
                    )}
                    <p className="text-[15px] text-gray-800 leading-relaxed break-words whitespace-pre-wrap">
                      {msg.content}
                    </p>
                  </div>
                </div>
              )
            })}
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  )
}
